Una suite que atrapa todo:

```js
test("acepta 8 caracteres", () => {
  expect(esClaveSegura("Abcdefg1")).toBe(true);
});
test("rechaza 7 caracteres", () => {
  expect(esClaveSegura("Abcdef1")).toBe(false);
});
test("acepta 20 caracteres", () => {
  expect(esClaveSegura("A1" + "x".repeat(18))).toBe(true);
});
test("rechaza 21 caracteres", () => {
  expect(esClaveSegura("A1" + "x".repeat(19))).toBe(false);
});
// y uno sin número y otro sin mayúscula, ambos con largo válido
```
